  baseNetDiscountAmount?: number;
  /** Item Amount before taxes, but after discounts = (grossAmount + netDiscountAmount) */
  netAmount?: number;
  /** netAmount allocated to base item (without considering options). For reporting */
  baseNetAmount?: number;
  /** tax on the item, present if unitPrice includes tax = sum(taxes.amountIncluded). If exists, provide taxes list. */
  taxAmountIncluded?: number;
  /** tax on the item, present if unitPrice excludes tax = sum(taxes.amountExcluded). If exists, provide taxes list. */
  taxAmountExcluded?: number;
  /** Total tax on this item = (taxAmountIncluded + taxAmountExcluded) */
  taxAmount?: number;
  /** taxAmount allocated to base item (without considering options). For reporting */
  baseTaxAmount?: number;
  /** Total cost for this item */
  itemCost?: number;
  /** Material cost for that item (Including Options) */
  itemMaterialCost?: number;
  /** Material cost for that item (Including Options) */
  itemSuppliesCost?: number;
  /**
   * Item notes/comments. Maximum 250 characters.
   * @maxLength 250
   */
  note?: string;
  /** Name of the user who added this item. If present, createdTime also should be present */
  createdBy?: string;
  /** time of item addition in ISO format with timezone (in branch timezone). If present, createdBy also should be present */
  createdTime?: string;
  /** Item options */
  options?: SaleItemsItemOptionsItem[];
  /** Discounts at item level. */
  discounts?: SaleItemsItemDiscountsItem[];
  /** Taxes at item level. */
  taxes?: SaleItemsItemTaxesItem[];
  /** Taxes at item level. */
  aggregatorTaxes?: SaleItemsItemAggregatorTaxesItem[];
  /** aggregator tax total */
