  /** Event/Activity Log */
  eventLog?: SaleItemsItemEventLogItem[];
  /** Batch details of line item, if any */
  batches?: SaleItemsItemBatchesItem[];
  /** Item KOT number. */
  kotNumber?: string;
  /** Item KOT Group. */
  kotGroup?: string;
  /** Item KOT generation timestamp */
  kotTimestamp?: string;
  /** Item KOT status. */
  kotStatus?: string;
  /** Timestamp when the item marked Ready on KDS */
