/**
 * Sale model
 */
export interface Sale {
  /** Name of the branch. If not provided, Rista will determine based on branchCode. */
  branchName?: string;
  /** Branch code */
  branchCode: string;
  /** Branch State */
  branchState?: string;
  /** Branch Tax Identification Number */
  branchTIN?: string;
  /** Unique identifier for a sale record, assigned by Rista */
  invoiceNumber?: string;
  /** Present in certain outlets where invoiceNumber is different from orderNumber. Assigned by Rista */
  orderNumber?: string;
  /** If this is a split invoice, statement number that this split is part of */
  statementNumber?: string;
  /** If this sale has splits, then gives all split invoice number */
  splitInvoiceNumbers?: string[];
  /** Date of sale in ISO format with timezone (in branch timezone), assigned by Rista */
  invoiceDate?: string;
  /**  Business Day this invoice accounted for in YYYY-MM-DD format */
  invoiceDay?: string;
  /** Information about sale EInvoice Info */
  einvoiceInfo?: SaleEinvoiceInfo;
  /** Date of sale creation in ISO format with timezone (in branch timezone), assigned by Rista */
  createdDate?: string;
  /** Date of last sale modification in ISO format with timezone (in branch timezone), assigned by Rista */
  modifiedDate?: string;
  /** Device label of the device where the sale was completed. */
  deviceLabel?: string;
  /** Transaction type, Sale/Return. Only Sale supported for input. */
  invoiceType?: SaleInvoiceType;
  /** Status of sale. Only Open/Closed supported for input. */
  status?: SaleStatus;
  /** Fulfillment status of sale */
  fulfillmentStatus?: SaleFulfillmentStatus;
  /** Information about sale record as in external source system. */
  sourceInfo?: SaleSourceInfo;
  /** Original sale info, present only if invoiceType=Return */
  originalSaleInfo?: SaleOriginalSaleInfo;
  /** Delivery information. */
  delivery?: SaleDelivery;
  /** Details of rider who delivered */
  deliveryBy?: SaleDeliveryBy;
  /** Service label e.g. Table 1. */
  label?: string;
  /** Service label group e.g. Outdoor, First floor etc. */
  labelGroup?: string;
  /** Session label e.g. Morning */
  sessionLabel?: string;
  /** PAX/group size/number of people */
  personCount?: number;
  /** Customer attached to sale. */
  customer?: SaleCustomer;
  /** Name of the user who performed this sale. */
  saleBy?: string;
  /** User id of the user who performed this sale. */
  saleByUserId?: string;
  /** Name of the price channel. */
  channel: string;
  /** Label of the price channel. */
  channelLabel?: string;
  /** Currency code of sale. If not provided, Rista will determine based on business currency. */
  currency?: string;
  /**
   * Number of items in sale. If not provided, Rista will determine based on no. of items.
   * @minimum 0
   */
  itemCount?: number;
  /** List of sale items */
  items: SaleItemsItem[];
  /** Timestamp when the order is marked In Process on KDS i.e. First timestamp when any of the ticket marked In Process on KDS */
  kdsOrderInProcess?: string;
  /** Timestamp when the complete order is marked processed on KDS i.e. all tickets of that item marked processed. */
  orderReadyTimestamp?: string;
  /** = sum(items.itemTotalAmount) */
  itemTotalAmount?: number;
  /** Total charge amount = sum(charges.amount) for charges marked as Direct. If exists, provide charges list. */
  directChargeAmount?: number;
  /** Total charge amount = sum(charges.amount) for charges not marked as Direct. If exists, provide charges list. */
  chargeAmount?: number;
  /** Total discount amount applied at sale level = sum(discounts.amount). If exists, value should less than zero and provide discounts list. */
  discountAmount?: number;
  /** sum of discounts applied at item level. Sum(item.discountAmount) */
  itemDiscountAmount?: number;
  /** total discount = (discountAmount + itemDiscountAmount) */
  totalDiscountAmount?: number;
  /** total of item taxes and charge taxes included in price =sum(items.taxAmountIncluded) + sum(charges.taxAmountIncluded). If exists, provide taxes list. */
  taxAmountIncluded?: number;
  /** total of item, charge taxes excluded in price = sum(items.taxAmountExcluded) + sum(charges.taxAmountExcluded). If exists, provide taxes list. */
  taxAmountExcluded?: number;
  /** Total tax amount = (taxAmountIncluded + taxAmountExcluded). If exists, provide taxes list. */
  taxAmount?: number;
  /** Bill Amount before discounts, charges and taxes = sum(items.grossAmount) */
  grossAmount?: number;
  /** totalDiscountAmount before taxes = sum(items.netDiscountAmount). */
  netDiscountAmount?: number;
  /** Total charge amount before tax on charge for those marked as Direct charge = sum(charges.amount - charges.taxAmountIncluded) */
  netDirectChargeAmount?: number;
  /** Bill Amount before taxes and charges, but after discounts = sum(items.netAmount) and same as (grossAmount + netDiscountAmount) */
  netAmount?: number;
  /** Total charge amount before tax on charge for those not marked as Direct charge = sum(charges.amount - charges.taxAmountIncluded) */
  netChargeAmount?: number;
  /** total bill amount = (itemTotalAmount + discountAmount + chargeAmount + taxAmountExcluded) and is same as = (netAmount + netChargeAmount + taxAmount) */
  billAmount?: number;
  /** Round off amount. */
  roundOffAmount?: number;
  /** billAmount + roundOffAmount */
  billRoundedAmount?: number;
  /** Tip amount. */
  tipAmount?: number;
  /** Total amount to be collected. billRoundedAmount + tipAmount */
  totalAmount?: number;
  /** Total Cost of All Sale Items */
  totalCost?: number;
  /** Total of all item material costs in that bill (Including Options) */
  totalMaterialCost?: number;
  /** Total of all item supplies costs in that bill (Including Options) */
  totalSuppliesCost?: number;
  /**
   * Sale notes/comments. Maximum 250 characters.
   * @maxLength 250
   */
  note?: string;
  /** Charges applied. */
  charges?: SaleChargesItem[];
  /** Discounts applied directly at bill level. */
  discounts?: SaleDiscountsItem[];
  /** Summary of taxes applied for items and charges. */
  taxes?: SaleTaxesItem[];
  /** Aggregator Taxes at order level. */
  aggregatorTaxes?: SaleAggregatorTaxesItem[];
  /** Order level aggregator tax total */
  aggregatorTaxTotal?: number;
  /** Summary of aggregator tax applied for items and charges */
  billAggregatorTaxes?: SaleBillAggregatorTaxesItem[];
  /** Total amount to be collected by aggregator */
  billAggregatorTaxAmount?: number;
  /** Payments for the sale. */
  payments?: SalePaymentsItem[];
  /** Overall refunds for the sale. */
  overallRefunds?: SaleOverallRefundsItem[];
  /** Loyalty Redeemed/Earned for this sale. */
  loyalties?: SaleLoyaltiesItem[];
  /** Rista sale url */
  url?: string;
  /** Information about current status if Cancelled/Voided */
  statusInfo?: SaleStatusInfo;
  /** Event/Activity Log */
  eventLog?: SaleEventLogItem[];
  /** Tags attached to sale, includes aggregator tagged information. */
  tags?: string[];
  /** The resource i.e., Table the order belongs to */
  resourceInfo?: SaleResourceInfo;
  /** Value of round off error cause due to inclusiveTax, order level discount projection to net price, etc */
  accountingRoundOff?: number;
}

